-- Verified local project only. Official Auth fixture identities; all mutations roll back.
begin;
create temporary table actors as select replace(full_name,'Teste ','') name,id from public.profiles where full_name like 'Teste %';
grant select on actors to authenticated;
create function pg_temp.assert_true(ok boolean,message text) returns void language plpgsql as $$begin if not coalesce(ok,false) then raise exception 'ASSERTION: %',message;end if;end;$$;
create function pg_temp.login(who text) returns void language plpgsql as $$begin perform pg_temp.assume_context(who,'ab000000-0000-4000-8000-000000000001');end;$$;
create function pg_temp.denied(statement text,message text) returns void language plpgsql as $$declare caught boolean:=false;begin begin execute statement;exception when others then caught:=true;end;perform pg_temp.assert_true(caught,message);end;$$;
grant execute on function pg_temp.assert_true(boolean,text),pg_temp.login(text),pg_temp.denied(text,text) to authenticated;
insert into public.care_recipients(id,display_name,is_development) values('ab000000-0000-4000-8000-000000000001','Invariantes fictícias A',true),('ab000000-0000-4000-8000-000000000002','Invariantes fictícias B',true);
insert into public.care_recipient_products(care_recipient_id,product_id,name,category,unit,aliases,sort_order)
select r.id,p.id,p.name,p.category,p.unit,p.aliases,0 from public.care_recipients r cross join (select * from public.products where owner_care_recipient_id is null order by id limit 10) p where r.id in ('ab000000-0000-4000-8000-000000000001','ab000000-0000-4000-8000-000000000002');
insert into public.care_recipient_memberships(care_recipient_id,user_id,role)
select 'ab000000-0000-4000-8000-000000000001',id,case when name in ('adminA','adminB') then 'admin'::public.profile_role else name::public.profile_role end from actors where name in ('adminA','adminB','family','supervisor','professional','reader');
set local role authenticated;
do $$
declare p uuid:='ab000000-0000-4000-8000-000000000001';p2 uuid:='ab000000-0000-4000-8000-000000000002';req record;d jsonb;e jsonb;b jsonb;c jsonb;payload jsonb;lines jsonb;f jsonb;x record;k uuid;v bigint;first_product text;policy jsonb;settings_version integer;report_id uuid;before_count integer;
begin
 perform pg_temp.login('adminA');
 for x in select product_id from public.care_recipient_products where care_recipient_id=p loop perform public.family_stock_movement(p,x.product_id,40,'inbound','Estoque familiar de teste',gen_random_uuid());end loop;
 select product_id into first_product from public.care_recipient_products where care_recipient_id=p order by product_id limit 1;
 perform pg_temp.denied(format('select source_balance_before from public.stock_movements where care_recipient_id=%L',p),'raw private balances have no client grant');
 select jsonb_agg(jsonb_build_object('productId',product_id,'currentStock',0,'urgent',false) order by product_id) into lines from public.care_recipient_products where care_recipient_id=p;
 perform pg_temp.login('professional');
 select * into req from public.submit_requisition(p,gen_random_uuid(),'untrusted',lines,'[]','[]');
 perform pg_temp.assert_true((select code='REQ-0001' from public.operational_documents where id=req.requisition_id),'patient/type sequence begins at one');
 perform pg_temp.denied(format('select public.submit_requisition(%L,gen_random_uuid(),''untrusted'',%L,''[]'',''[]'')',p,lines),'duplicate requires explicit justification');
 perform pg_temp.assert_true(not exists(select 1 from public.current_stock_balances where care_recipient_id=p and location='FAMILY'),'team cannot read general family stock');
 perform pg_temp.assert_true((public.stock_overview(p)->0->'family')='null'::jsonb,'family overview is masked');
 perform pg_temp.login('family');
 select jsonb_build_object('source','FAMILY','destination','CARE_TEAM','recipientId',(select id from actors where name='professional'),'lines',jsonb_agg(jsonb_build_object('productId',i.product_id,'quantity','10','requisitionItemIds',jsonb_build_array(i.id)) order by i.product_id)) into payload from (select * from public.requisition_items where requisition_id=req.requisition_id order by product_id limit 5) i;
 d:=public.create_supply_document(p,'ENT',payload,gen_random_uuid(),false);
 perform pg_temp.assert_true(d->>'status'='pending_receipt' and (d->>'fullyCheckedLines')::integer=0,'issuing is not receiving');
 perform pg_temp.denied(format('select public.supply_document_command(%L,''receive'',''{"divergences":[]}'',gen_random_uuid(),%s)',d->>'id',d->>'version'),'issuer cannot accept');
 perform pg_temp.login('professional');
 perform pg_temp.denied(format('select public.supply_document_command(%L,''receive'',''{}'',gen_random_uuid(),%s)',d->>'id',d->>'version'),'missing arrays rejected by database');
 k:=gen_random_uuid();v:=(d->>'version')::integer;
 f:=jsonb_build_object('divergences',jsonb_build_array(jsonb_build_object('lineId',d->'lines'->0->>'id','acceptedQuantity','6','problem','Quatro unidades faltantes')));
 d:=public.supply_document_command((d->>'id')::uuid,'receive',f,k,v::integer);
 perform pg_temp.assert_true(d->>'status'='disputed' and (d->>'fullyCheckedLines')::integer=4,'partial positive receipt does not fully check ENT line');
 e:=public.supply_document_command((d->>'id')::uuid,'receive',f,k,v::integer);
 perform pg_temp.assert_true(e->>'version'=d->>'version','retry does not apply receipt twice');
 f:=public.requisition_fulfillment(req.requisition_id);
 perform pg_temp.assert_true(f->>'fulfilled'='5' and f->>'total'='10','REQ displays five of ten items attended');
 perform pg_temp.denied(format('select public.supply_document_command(%L,''reassign'',%L,gen_random_uuid(),%s)',d->>'id',jsonb_build_object('recipientId',(select id from actors where name='supervisor'),'reason','Troca após aceite'),d->>'version'),'recipient immutable after first positive acceptance');
 perform pg_temp.login('adminA');
 d:=public.supply_document_command((d->>'id')::uuid,'resolve',jsonb_build_object('lineId',d->'lines'->0->>'id','quantity','4','resolution','missing','reason','Falta definitiva conciliada'),gen_random_uuid(),(d->>'version')::integer);
 perform pg_temp.assert_true(d->>'status'='confirmed' and d->>'fullyCheckedLines'='4','ENT can close with formal quantity reconciliation without pretending full receipt');
 perform pg_temp.login('family');
 select jsonb_build_object('source','FAMILY','destination','CARE_TEAM','recipientId',(select id from actors where name='professional'),'lines',jsonb_agg(jsonb_build_object('productId',product_id,'quantity','10'))) into payload from public.care_recipient_products where care_recipient_id=p;
 e:=public.create_supply_document(p,'ENT',payload,gen_random_uuid(),false);
 perform pg_temp.login('professional');
 f:=jsonb_build_object('divergences',jsonb_build_array(jsonb_build_object('lineId',e->'lines'->8->>'id','acceptedQuantity','0'),jsonb_build_object('lineId',e->'lines'->9->>'id','acceptedQuantity','0')));
 e:=public.supply_document_command((e->>'id')::uuid,'receive',f,gen_random_uuid(),(e->>'version')::integer);
 perform pg_temp.assert_true(e->>'fullyCheckedLines'='8' and e->>'status'='disputed','ENT shows eight of ten fully checked');
 perform pg_temp.assert_true(public.requisition_fulfillment(req.requisition_id)->>'fulfilled'='5','unlinked ENT must not attend other pending REQ lines');
 perform pg_temp.denied(format('select public.supply_document_command(%L,''receive'',''{"divergences":[]}'',gen_random_uuid(),1)',e->>'id'),'stale or second receive is denied');
 perform pg_temp.login('family');
 perform pg_temp.denied(format('select public.supply_document_command(%L,''cancel'',''{"reason":"Cancelar após aceite"}'',gen_random_uuid(),%s)',d->>'id',d->>'version'),'family cannot request post-acceptance cancellation');
 perform pg_temp.login('adminA');
 d:=public.supply_document_command((d->>'id')::uuid,'cancel','{"reason":"Entrega anterior será cancelada com devolução real"}',gen_random_uuid(),(d->>'version')::integer);
 perform pg_temp.assert_true(d->>'status'='cancellation_pending','admin request waits for original recipient consent');
 select jsonb_build_object('reason','Devolvi o material aceito','lines',jsonb_agg(jsonb_build_object('lineId',value->>'id','returnQuantity',value->>'accepted_quantity','consumedQuantity','0'))) into f from jsonb_array_elements(d->'lines');
 perform pg_temp.login('supervisor');
 perform pg_temp.denied(format('select public.supply_document_command(%L,''consent_cancel'',%L,gen_random_uuid(),%s)',d->>'id',f,d->>'version'),'another team professional cannot consent');
 perform pg_temp.login('professional');
 d:=public.supply_document_command((d->>'id')::uuid,'consent_cancel',f,gen_random_uuid(),(d->>'version')::integer);
 perform pg_temp.assert_true(d->>'status'='cancelled' and public.requisition_fulfillment(req.requisition_id)->>'fulfilled'='0','compensation removes physical fulfillment without deleting acceptance history');
 perform pg_temp.login('adminA');
 select version into settings_version from public.patient_settings where care_recipient_id=p;
 policy:=public.configure_patient_access(p,'settings','{"balReview":"required","balApprovers":["family","supervisor"],"balRequirement":"all"}',gen_random_uuid(),settings_version);
 perform pg_temp.assert_true(policy->>'status'='applied','authorized local policy applies immediately');
 perform pg_temp.login('professional');
 select jsonb_build_object('lines',jsonb_agg(jsonb_build_object('productId',product_id,'quantity','7'))) into payload from public.care_recipient_products where care_recipient_id=p;
 b:=public.create_supply_document(p,'BAL',payload,gen_random_uuid(),false);
 perform pg_temp.assert_true(b->>'status'='submitted','required BAL remains pending');
 perform pg_temp.login('family');
 b:=public.supply_document_command((b->>'id')::uuid,'approve','{"group":"family"}',gen_random_uuid(),(b->>'version')::integer);
 perform pg_temp.assert_true(b->>'status'='submitted','one review cannot stand for both groups');
 perform pg_temp.login('adminA');
 c:=public.create_supply_document(p,'ENT',jsonb_build_object('source','FAMILY','destination','CARE_TEAM','recipientId',(select id from actors where name='professional'),'lines',jsonb_build_array(jsonb_build_object('productId',first_product,'quantity','1'))),gen_random_uuid(),false);
 perform pg_temp.login('supervisor');
 perform pg_temp.denied(format('select public.supply_document_command(%L,''approve'',''{"group":"supervisor"}'',gen_random_uuid(),%s)',b->>'id',b->>'version'),'movement after BAL reference requires recount');
 perform pg_temp.login('professional');
 b:=public.revise_supply_document((b->>'id')::uuid,payload,gen_random_uuid(),(b->>'version')::integer,true);
 perform pg_temp.login('supervisor');
 b:=public.supply_document_command((b->>'id')::uuid,'approve','{"group":"supervisor"}',gen_random_uuid(),(b->>'version')::integer);
 perform pg_temp.assert_true(b->>'status'='submitted','prior count approval does not approve recount');
 perform pg_temp.login('family');
 b:=public.supply_document_command((b->>'id')::uuid,'approve','{"group":"family"}',gen_random_uuid(),(b->>'version')::integer);
 perform pg_temp.assert_true(b->>'status'='approved','distinct groups approve current recount');
 perform pg_temp.login('professional');
 report_id:=public.report_extraordinary_consumption(p,'consumption','CARE_TEAM','Consumo confirmado de teste',jsonb_build_array(jsonb_build_object('productId',first_product,'quantity','2')),gen_random_uuid());
 perform pg_temp.assert_true((select balance=7 from public.current_stock_balances where care_recipient_id=p and product_id=first_product and location='CARE_TEAM'),'unconfirmed report does not debit');
 perform pg_temp.login('supervisor');perform public.confirm_extraordinary_consumption(report_id,true);perform public.confirm_extraordinary_consumption(report_id,true);
 perform pg_temp.assert_true((select balance=5 from public.current_stock_balances where care_recipient_id=p and product_id=first_product and location='CARE_TEAM'),'confirmed report debits exactly once');
 perform pg_temp.login('adminA');
 perform public.admin_upsert_membership(p,(select id from actors where name='reader'),'admin',false,false);
 perform pg_temp.assert_true((select role='admin' from public.care_recipient_memberships where care_recipient_id=p and user_id=(select id from actors where name='reader')),'local administrator applies membership change immediately');
 perform public.admin_upsert_membership(p,(select id from actors where name='reader'),'reader',false,false);
 perform pg_temp.denied(format('select public.family_stock_movement(%L,%L,999999,''outbound'',''Retirada superior ao disponível'',gen_random_uuid())',p,first_product),'manual movement cannot spend transit or unavailable quantities');
 perform pg_temp.assert_true(not has_function_privilege('authenticated','private.move_stock(uuid,text,numeric,text,text,text,text,uuid)','execute'),'internal ledger helper is not executable by client');
 perform pg_temp.denied(format('update public.document_events set content_hash=repeat(''0'',64) where document_id=%L',d->>'id'),'confirmed event mutation denied');
 perform pg_temp.login('reader');
 perform pg_temp.denied(format('select public.create_supply_document(%L,''COM'',%L,gen_random_uuid(),false)',p,payload),'reader cannot create COM');
 perform pg_temp.denied(format('select public.operational_document(%L)',(select id from public.operational_documents where care_recipient_id=p2 limit 1)),'cross-patient document read denied');
end;$$;
reset role;
select pg_temp.assert_true(not exists(select 1 from public.document_events where content_hash<>encode(extensions.digest(body::text,'sha256'),'hex')),'every event hash matches canonical database content');
select 'document invariant regressions passed';
rollback;
